pm.test("Default response contains 20 products", function () {
    pm.expect(pm.response.json().length).to.eql(20);
});

pm.test("Every product has id, category, name, inStock with correct types", function () {
    pm.response.json().forEach(function (p) {
        pm.expect(p.id).to.be.a('number');
        pm.expect(p.category).to.be.a('string');
        pm.expect(p.name).to.be.a('string');
        pm.expect(p.inStock).to.be.a('boolean');
    });
});

pm.test("Product ids are unique", function () {
    const ids = pm.response.json().map(p => p.id);
    pm.expect(new Set(ids).size).to.eql(ids.length);
});

